/** Areas named explicitly in the page's H2, used for schema areaServed. */
export const PRIMARY_AREAS = [
  "Las Vegas",
  "Summerlin",
  "Henderson",
  "North Las Vegas",
  "Spring Valley",
] as const;

export interface Faq {
  q: string;
  a: string;
}

const postalAddress = () => ({
  "@type": "PostalAddress",
  streetAddress: BUSINESS.address.street,
  addressLocality: BUSINESS.address.city,
  addressRegion: BUSINESS.address.region,
  postalCode: BUSINESS.address.postalCode,
  addressCountry: BUSINESS.address.country,
});

/**
 * The single LocalBusiness node. Every other node references it by @id rather
 * than nesting its own copy, so a page can never emit two LocalBusiness blocks.
 */
export const LOCAL_BUSINESS_ID = `${BUSINESS.url}/#localbusiness`;

export const localBusinessSchema = () => ({
  "@type": "LocalBusiness",
  "@id": LOCAL_BUSINESS_ID,
  name: BUSINESS.name,
  url: BUSINESS.url,
  telephone: BUSINESS.phoneDisplay,
  address: postalAddress(),
  geo: {
    "@type": "GeoCoordinates",
    latitude: BUSINESS.geo.latitude,
    longitude: BUSINESS.geo.longitude,
  },
  aggregateRating: {
    "@type": "AggregateRating",
    ratingValue: BUSINESS.rating.value,
    reviewCount: BUSINESS.rating.count,
    bestRating: BUSINESS.rating.best,
    worstRating: BUSINESS.rating.worst,
  },
  priceRange: "$$",
  foundingDate: BUSINESS.founded,
  openingHoursSpecification: [
    {
      "@type": "OpeningHoursSpecification",
      dayOfWeek: [...BUSINESS.hours.days],
      opens: BUSINESS.hours.opens,
      closes: BUSINESS.hours.closes,
    },
  ],
});

export const serviceSchema = (pageUrl: string) => ({
  "@type": "Service",
  "@id": `${pageUrl}#service`,
  name: "Frameless Shower Door Installation",
  serviceType: "Frameless Shower Door Installation",
  description:
    "Custom frameless glass shower doors for Las Vegas homes — measured in your bathroom, fabricated to your opening, and installed by in-house licensed installers.",
  provider: { "@id": LOCAL_BUSINESS_ID },
  areaServed: PRIMARY_AREAS.map((name) => ({
    "@type": "City",
    name,
    addressRegion: BUSINESS.address.region,
  })),
});

export const faqPageSchema = (faqs: readonly Faq[]) => ({
  "@type": "FAQPage",
  mainEntity: faqs.map((faq) => ({
    "@type": "Question",
    name: faq.q,
    acceptedAnswer: { "@type": "Answer", text: faq.a },
  })),
});

/**
 * Builds the complete @graph for a page: exactly one LocalBusiness, one
 * Service, one FAQPage.
 */
export const buildPageSchema = (pageUrl: string, faqs: readonly Faq[]) => ({
  "@context": "https://schema.org",
  "@graph": [localBusinessSchema(), serviceSchema(pageUrl), faqPageSchema(faqs)],
});
